#!/usr/bin/env bash
set -e

# RCAR 2026 accommodation + Seychelles entry notice update.
#
# What it does:
# 1) Rewrites accommodation.html into a concise two-hotel layout:
#    - Coral Strand Smart Choice Hotel: one photo + clear nightly room-rate table
#    - Savoy Resort & Spa Seychelles: one photo + clear nightly room-rate table
# 2) Adds an important Seychelles Travel Authorisation notice to:
#    - index.html
#    - venue.html
# 3) Uses the official conference email: ieeercar@163.com
#
# Run in /var/www/rcar2026.

CONFERENCE_EMAIL="${CONFERENCE_EMAIL:-ieeercar@163.com}"

ts="$(date +%Y%m%d_%H%M%S)"
backup_dir="backup_accommodation_entry_notice_${ts}"
mkdir -p "$backup_dir"

cp accommodation.html index.html venue.html nav1.html "$backup_dir"/ 2>/dev/null || true

mkdir -p Images

echo "[1/5] Writing hotel photos..."

cat > /tmp/coral_strand_room.b64 <<'EOF_CORAL_IMG'
