        .hero { margin-top:24px; border:1px solid #d9e5e8; border-radius:18px; padding:28px 32px; background:linear-gradient(135deg,#edf8ff 0%,#edf9f6 55%,#fff7e8 100%); box-shadow:0 14px 32px rgba(30,80,100,.10); text-align:left; }
        .title { color:#27445c; margin-top:0; font-size:32pt; text-align:center; letter-spacing:.5px; }
        .title:after { content:""; display:block; width:76px; height:3px; margin:12px auto 0; border-radius:3px; background:linear-gradient(90deg,#1677b3,#1aa39a); }
        .lead { max-width:980px; margin:18px auto 0; font-size:15.2pt; line-height:1.75; text-align:left; color:#31444f; }
        .notice { border-left:5px solid #1aa39a; background:#f5fbfa; padding:14px 18px; margin-top:18px; font-size:14.5pt; line-height:1.7; text-align:left; }
        .warning { border-left:5px solid #d99a22; background:#fff9ed; padding:14px 18px; margin-top:18px; font-size:14.5pt; line-height:1.7; text-align:left; }
        .section-title { color:#27445c; font-size:22pt; font-weight:bold; margin-top:32px; margin-bottom:16px; padding-left:12px; border-left:5px solid #1aa39a; text-align:left; }
        .hotel-card { border:1px solid #d9e5e8; border-radius:18px; background:#fff; overflow:hidden; margin-bottom:30px; box-shadow:0 12px 28px rgba(30,70,90,.10); }
        .hotel-photo { width:100%; height:270px; object-fit:cover; display:block; }
        .hotel-body { padding:22px 24px; }
        .hotel-title { color:#27445c; font-size:22pt; font-weight:bold; margin:0 0 8px; }
        .hotel-meta { color:#5d6d75; font-size:14pt; margin-bottom:16px; line-height:1.55; }
        .rate-table { width:100%; border-collapse:collapse; font-size:13.5pt; color:#2f3e46; background:#fff; }
        .rate-table th { background:#e7f3f6; color:#27445c; font-weight:bold; border:1px solid #bfd4dc; padding:10px; text-align:left; }
        .rate-table td { border:1px solid #d5e3e8; padding:10px; vertical-align:top; line-height:1.5; text-align:left; }
        .rate-table tr:nth-child(even) td { background:#fbfdfe; }
        .note-list { font-size:14.5pt; line-height:1.65; text-align:left; padding-left:22px; margin-bottom:0; }
        .note-list li { margin-top:8px; }
        .muted { color:#66757d; }
        @media(max-width:768px) {
            .title { font-size:26pt; }
            .lead { font-size:14pt; }
            .section-title { font-size:19pt; }
            .hotel-photo { height:210px; }
            .hotel-title { font-size:19pt; }
            .rate-table { font-size:12.2pt; }
        }
    </style>

    <script src="./Scripts/jquery-1.11.3.js?v=20220702"></script>
    <script src="./Scripts/jquery.countdown.js?v=20220702"></script>
    <script src="./Scripts/viewportchecker.min.js?v=20220702"></script>
</head>

<body data-spy="scroll" data-target=".navbar" data-offset="50">
$(cat /tmp/rcar_nav_fixed.html)

    <div class="container page">
        <div class="hero">
            <p class="title">Accommodation</p>
            <p class="lead">
