</html>
EOF_ACCOM

echo "[4/5] Adding Travel Authorisation notice to index.html and venue.html..."

cat > /tmp/travel_authorisation_notice.html <<EOF_NOTICE
<!-- RCAR_ENTRY_NOTICE_START -->
<div class="container entry-notice-section">
    <div class="entry-notice-box">
        <p class="entry-notice-title">Important Entry Requirement: Seychelles Travel Authorisation</p>
        <p class="entry-notice-text">
            Although no visa is generally required for visitors to Seychelles, <strong>all travellers are required to apply for a Travel Authorisation (TA) before travelling to Seychelles</strong>.
            Participants may apply online through the
            <a href="https://seychelles.govtas.com/en" target="_blank" rel="noopener noreferrer">Seychelles Electronic Border System</a>
            or the Seychelles E-Border app. Please prepare a valid passport, selfie, contact information, trip information,
            airline booking confirmation, accommodation booking confirmation, and credit/debit card information.
        </p>
    </div>
</div>
<!-- RCAR_ENTRY_NOTICE_END -->
EOF_NOTICE

cat > /tmp/travel_authorisation_notice_css.txt <<'EOF_CSS'
        .entry-notice-section {
            margin-top: 24px;
            margin-bottom: 24px;
        }
        .entry-notice-box {
            border-left: 6px solid #d99a22;
            border-radius: 14px;
            padding: 18px 22px;
            background: #fff9ed;
            box-shadow: 0 8px 22px rgba(90, 70, 30, 0.08);
            text-align: left;
        }
        .entry-notice-title {
            color: #27445c;
            font-size: 19pt;
            font-weight: bold;
            margin: 0 0 8px 0;
        }
        .entry-notice-text {
            font-size: 14.5pt;
            line-height: 1.7;
            color: #2f3e46;
            margin-bottom: 0;
            text-align: left;
        }
        @media(max-width:768px) {
            .entry-notice-title { font-size: 17pt; }
            .entry-notice-text { font-size: 13.5pt; }
        }
EOF_CSS

add_entry_css_if_missing() {
    f="$1"
    [ -f "$f" ] || return 0
    if grep -q "entry-notice-section" "$f"; then
        return 0
    fi
    if grep -q "</style>" "$f"; then
        awk '
            FNR==NR { css = css $0 ORS; next }
            /<\/style>/ && !inserted {
                printf "%s", css
                inserted = 1
            }
            { print }
        ' /tmp/travel_authorisation_notice_css.txt "$f" > "$f.tmp" && mv "$f.tmp" "$f"
    else
        awk '
            FNR==NR { css = css $0 ORS; next }
            /<\/head>/ && !inserted {
                print "    <style>"
                printf "%s", css
                print "    </style>"
                inserted = 1
            }
            { print }
        ' /tmp/travel_authorisation_notice_css.txt "$f" > "$f.tmp" && mv "$f.tmp" "$f"
    fi
}

insert_entry_notice_after_nav() {
    f="$1"
    [ -f "$f" ] || return 0

    sed -i '/<!-- RCAR_ENTRY_NOTICE_START -->/,/<!-- RCAR_ENTRY_NOTICE_END -->/d' "$f"

    awk '
        FNR==NR { block = block $0 ORS; next }
        /<\/nav>/ && !inserted {
            print
            printf "%s", block
            inserted = 1
            next
        }
        /<include src="nav1.html"><\/include>/ && !inserted {
            print
            printf "%s", block
            inserted = 1
            next
        }
        { print }
    ' /tmp/travel_authorisation_notice.html "$f" > "$f.tmp" && mv "$f.tmp" "$f"
}

for f in index.html venue.html; do
    if [ -f "$f" ]; then
        add_entry_css_if_missing "$f"
        insert_entry_notice_after_nav "$f"
    fi
done

echo "[5/5] Checks..."

echo "---- Hotel price checks ----"
grep -n "Coral Strand Smart Choice Hotel\|Savoy Resort\|USD 269\|USD 388\|SCR 100" accommodation.html || true

echo "---- Entry notice checks ----"
grep -Rni "Seychelles Travel Authorisation\|Travel Authorisation (TA)\|seychelles.govtas.com" index.html venue.html accommodation.html || true

echo "---- Image checks ----"
ls -lh Images/coral_strand_room.jpg Images/savoy_room.jpg

echo "Done. Backup directory: $backup_dir"
